sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Find the Staff group — every new task starts here
    var staffGroup = new GlideRecord('sys_user_group');
    staffGroup.addQuery('name', 'Mess Staff Group');
    staffGroup.query();

    if (!staffGroup.next()) {
        gs.warn('Mess Staff Group not found — cannot create task for ' + current.number);
        return;
    }

    var task = new GlideRecord('x_snc_campus_foo_1_problem_task');
    task.initialize();
    task.parent_base_problem = current.getUniqueValue();
    task.assignment_group = staffGroup.getUniqueValue();
    task.priority = current.current_priority;
    task.short_description = 'Resolve recurring issue: ' + current.problem_type;
    task.state = 1; // New
    task.insert();

    gs.info('Created task for new Base Problem: ' + current.number);

})(current, previous);
